all_us_cafes = houston_cafes + miami_cafes + dallas_cafes + austin_cafes + phoenix_cafes + atlanta_cafes + tampa_cafes + orlando_cafes + charlotte_cafes + denver_cafes + vegas_cafes

with open('data/leads_bundle.js', 'r', encoding='utf-8') as f:
    text = f.read()

m = re.search(r"window\.LONDON_LEADS_DATA\s*=\s*(\{[\s\S]*?\});\s*(?:window\.UK_LEADS_DATA|$)", text)
if not m:
    raise ValueError("Could not find window.LONDON_LEADS_DATA in leads_bundle.js")

bundle = json.loads(m.group(1))

all_us_city_names = ["Houston", "Miami", "Dallas", "Austin", "Phoenix", "Atlanta", "Tampa", "Orlando", "Charlotte", "Denver", "Las Vegas"]

# Filter out old entries for US cities
for cat in ["salons", "estate_agents", "dentists", "restaurants", "cafes"]:
    bundle[cat] = [l for l in bundle[cat] if l.get("city") not in all_us_city_names]

# Append updated leads
bundle["salons"].extend(all_us_salons)
bundle["estate_agents"].extend(all_us_estate)
bundle["dentists"].extend(all_us_dentists)
bundle["restaurants"].extend(all_us_restaurants)
bundle["cafes"].extend(all_us_cafes)

bundle_content = """/**
 * Global Multi-City Business Leads Pre-Bundled Dataset
 * Covers US (Houston, Miami, Dallas, Austin, Phoenix, Atlanta, Tampa, Orlando, Charlotte, Denver, Las Vegas),
 * UK (London, Manchester, Birmingham, Leeds, Liverpool, Edinburgh),
 * and UAE (Dubai, Abu Dhabi).
 * Verified with Meta WhatsApp API for zero-latency direct outreach.
 */
window.LONDON_LEADS_DATA = """ + json.dumps(bundle, indent=2) + """;
window.UK_LEADS_DATA = window.LONDON_LEADS_DATA;
"""

with open('data/leads_bundle.js', 'w', encoding='utf-8') as f:
    f.write(bundle_content)

# Save standalone JSON for each US city
for c in all_us_city_names:
    city_leads = [l for cat in ["salons", "estate_agents", "dentists", "restaurants", "cafes"] for l in bundle[cat] if l.get("city") == c]
    fn = f"data/{c.lower().replace(' ', '_')}_leads.json"
    with open(fn, 'w', encoding='utf-8') as f:
        json.dump(city_leads, f, indent=2)

print(f"Successfully compiled leads across {len(all_us_city_names)} US growth markets including Miami!")
total = sum(len(bundle[c]) for c in ["salons", "estate_agents", "dentists", "restaurants", "cafes"])
print(f"Total leads across all global cities in leads_bundle.js: {total}")
for c in all_us_city_names + ["London", "Manchester", "Birmingham", "Leeds", "Liverpool", "Edinburgh", "Dubai", "Abu Dhabi"]:
    cnt = sum(len([l for l in bundle[cat] if l.get('city') == c]) for cat in ["salons", "estate_agents", "dentists", "restaurants", "cafes"])
    verified_cnt = sum(len([l for l in bundle[cat] if l.get('city') == c and l.get('whatsapp_live_verified')]) for cat in ["salons", "estate_agents", "dentists", "restaurants", "cafes"])
    print(f"  {c}: {cnt} leads ({verified_cnt} Meta live verified WhatsApp)")
